-- Create "trades" table
CREATE TABLE "trades" ("id" uuid NOT NULL, "create_time" timestamptz NOT NULL, "update_time" timestamptz NOT NULL, "liens" bigint NOT NULL DEFAULT 0, "offer_cards" jsonb NOT NULL, "receive_cards" jsonb NOT NULL, "initiator_id" character varying NOT NULL, "receiver_id" character varying NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "trades_players_initiator" FOREIGN KEY ("initiator_id") REFERENCES "players" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "trades_players_receiver" FOREIGN KEY ("receiver_id") REFERENCES "players" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
